namespace sv_2459d1cd92d4412e91c249149d3ab048.Services;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@rendermode InteractiveServer
@using sv_2459d1cd92d4412e91c249149d3ab048.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@* Step Indicator Bar *@
<div class="step-indicator">
    @for (int i = 0; i < stepNames.Length; i++)
    {
        var stepIndex = i;
        var cssClass = GetStepClass(stepIndex);
        <div class="step @cssClass" @onclick="() => GoToStep(stepIndex)">
            <div class="step-circle">
                @if (stepIndex < currentStep)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@stepNames[stepIndex]</div>
        </div>
        @if (i < stepNames.Length - 1)
        {
            <div class="step-connector @(stepIndex < currentStep ? "completed" : "")"></div>
        }
    }
</div>

@if (!string.IsNullOrEmpty(errorMessage))
{
    <div class="alert alert-danger mt-3">@errorMessage</div>
}

@* Step Content *@
<div class="step-content mt-4">
    @switch (currentStep)
    {
        case 0:
            @* Personal Info *@
            <h3>Personal Information</h3>
            <div class="mb-3">
                <label class="form-label">Full Name *</label>
                <input type="text" class="form-control" @bind="fullName" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email *</label>
                <input type="email" class="form-control" @bind="email" />
            </div>
            <div class="mb-3">
                <label class="form-label">Phone *</label>
                <input type="tel" class="form-control" @bind="phone" />
            </div>
            <div class="mb-3">
                <label class="form-label">Address *</label>
                <input type="text" class="form-control" @bind="address" />
            </div>
            <div class="d-flex justify-content-end">
                <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@isProcessing">
                    @if (isProcessing) { <span>Validating...</span> } else { <span>Next</span> }
                </button>
            </div>
            break;

        case 1:
            @* Work History *@
            <h3>Work History</h3>
            @for (int i = 0; i < workEntries.Count; i++)
            {
                var idx = i;
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h5 class="card-title mb-0">Position @(idx + 1)</h5>
                            @if (workEntries.Count > 1)
                            {
                                <button class="btn btn-sm btn-outline-danger" @onclick="() => RemoveWorkEntry(idx)">Remove</button>
                            }
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Company Name *</label>
                            <input type="text" class="form-control" @bind="workEntries[idx].Company" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Job Title *</label>
                            <input type="text" class="form-control" @bind="workEntries[idx].Title" />
                        </div>
                        <div class="row mb-3">
                            <div class="col-md-6">
                                <label class="form-label">Start Date *</label>
                                <input type="date" class="form-control" @bind="workEntries[idx].StartDate" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">End Date</label>
                                <input type="date" class="form-control" @bind="workEntries[idx].EndDate" disabled="@workEntries[idx].IsCurrent" />
                                <div class="form-check mt-1">
                                    <input type="checkbox" class="form-check-input" id="current-@idx" @bind="workEntries[idx].IsCurrent" />
                                    <label class="form-check-label" for="current-@idx">Currently working here</label>
                                </div>
                            </div>
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Description</label>
                            <textarea class="form-control" rows="3" @bind="workEntries[idx].Description"></textarea>
                        </div>
                    </div>
                </div>
            }
            <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="Back">Back</button>
                <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
            </div>
            break;

        case 2:
            @* References *@
            <h3>References</h3>
            @for (int i = 0; i < references.Count; i++)
            {
                var idx = i;
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h5 class="card-title mb-0">Reference @(idx + 1)</h5>
                            @if (references.Count > 2)
                            {
                                <button class="btn btn-sm btn-outline-danger" @onclick="() => RemoveReference(idx)">Remove</button>
                            }
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Name *</label>
                            <input type="text" class="form-control" @bind="references[idx].Name" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Relationship *</label>
                            <input type="text" class="form-control" @bind="references[idx].Relationship" />
                        </div>
                        <div class="row mb-3">
                            <div class="col-md-6">
                                <label class="form-label">Email *</label>
                                <input type="email" class="form-control" @bind="references[idx].Email" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Phone *</label>
                                <input type="tel" class="form-control" @bind="references[idx].Phone" />
                            </div>
                        </div>
                    </div>
                </div>
            }
            @if (references.Count < 3)
            {
                <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
            }
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="Back">Back</button>
                <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
            </div>
            break;

        case 3:
            @* Cover Letter *@
            <h3>Cover Letter</h3>
            <div class="mb-3">
                <textarea class="form-control" rows="12" maxlength="2000" @bind="coverLetter" @bind:event="oninput"></textarea>
                <div class="form-text text-end">@coverLetter.Length / 2000 characters</div>
            </div>
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="Back">Back</button>
                <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
            </div>
            break;

        case 4:
            @* Review & Submit *@
            @if (isSubmitted)
            {
                <div class="alert alert-success">
                    <h4>Application Submitted Successfully!</h4>
                    <p>Your application ID is: <strong>@applicationId</strong></p>
                </div>
            }
            else
            {
                <h3>Review & Submit</h3>

                @* Personal Info Summary *@
                <div class="card mb-3">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>Personal Information</strong>
                        <a href="javascript:void(0)" @onclick='() => GoToStep(0)'>Edit</a>
                    </div>
                    <div class="card-body">
                        <p><strong>Name:</strong> @fullName</p>
                        <p><strong>Email:</strong> @email</p>
                        <p><strong>Phone:</strong> @phone</p>
                        <p><strong>Address:</strong> @address</p>
                    </div>
                </div>

                @* Work History Summary *@
                <div class="card mb-3">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>Work History</strong>
                        <a href="javascript:void(0)" @onclick='() => GoToStep(1)'>Edit</a>
                    </div>
                    <div class="card-body">
                        @foreach (var entry in workEntries)
                        {
                            <div class="mb-2">
                                <p class="mb-1"><strong>@entry.Title</strong> at @entry.Company</p>
                                <p class="mb-1 text-muted">
                                    @entry.StartDate.ToString("MMM yyyy") &ndash;
                                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                                </p>
                                @if (!string.IsNullOrWhiteSpace(entry.Description))
                                {
                                    <p class="mb-0">@entry.Description</p>
                                }
                            </div>
                            <hr />
                        }
                    </div>
                </div>

                @* References Summary *@
                <div class="card mb-3">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>References</strong>
                        <a href="javascript:void(0)" @onclick='() => GoToStep(2)'>Edit</a>
                    </div>
                    <div class="card-body">
                        @foreach (var r in references)
                        {
                            <p class="mb-1"><strong>@r.Name</strong> (@r.Relationship) &mdash; @r.Email, @r.Phone</p>
                        }
                    </div>
                </div>

                @* Cover Letter Summary *@
                <div class="card mb-3">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>Cover Letter</strong>
                        <a href="javascript:void(0)" @onclick='() => GoToStep(3)'>Edit</a>
                    </div>
                    <div class="card-body">
                        <p style="white-space: pre-wrap;">@coverLetter</p>
                    </div>
                </div>

                <div class="d-flex justify-content-between">
                    <button class="btn btn-secondary" @onclick="Back">Back</button>
                    <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@isProcessing">
                        @if (isProcessing) { <span>Submitting...</span> } else { <span>Submit Application</span> }
                    </button>
                </div>
            }
            break;
    }
</div>

@code {
    private static readonly string[] stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int currentStep = 0;
    private int highestCompletedStep = -1;
    private string errorMessage = "";
    private bool isProcessing = false;
    private bool isSubmitted = false;
    private int applicationId;

    // Step 1 — Personal Info
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2 — Work History
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };

    // Step 3 — References
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 — Cover Letter
    private string coverLetter = "";

    private string GetStepClass(int step)
    {
        if (step == currentStep) return "active";
        if (step <= highestCompletedStep) return "completed";
        return "dimmed";
    }

    private void GoToStep(int step)
    {
        if (step <= highestCompletedStep)
        {
            currentStep = step;
            errorMessage = "";
        }
    }

    private void Back()
    {
        errorMessage = "";
        currentStep--;
    }

    // Step 1 validation
    private async Task NextFromPersonalInfo()
    {
        errorMessage = "";

        if (string.IsNullOrWhiteSpace(fullName) || string.IsNullOrWhiteSpace(email) ||
            string.IsNullOrWhiteSpace(phone) || string.IsNullOrWhiteSpace(address))
        {
            errorMessage = "All fields are required.";
            return;
        }

        isProcessing = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(email);
            if (!emailValid)
            {
                errorMessage = "The email address is not valid.";
                return;
            }
        }
        finally
        {
            isProcessing = false;
        }

        AdvanceStep();
    }

    // Step 2 validation
    private void NextFromWorkHistory()
    {
        errorMessage = "";
        foreach (var entry in workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate == default)
            {
                errorMessage = "Company, title, and start date are required for each position.";
                return;
            }
        }
        AdvanceStep();
    }

    // Step 3 validation
    private void NextFromReferences()
    {
        errorMessage = "";
        foreach (var r in references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                errorMessage = "All fields are required for each reference.";
                return;
            }
        }
        AdvanceStep();
    }

    // Step 4 validation
    private void NextFromCoverLetter()
    {
        errorMessage = "";
        if (string.IsNullOrWhiteSpace(coverLetter))
        {
            errorMessage = "Please enter a cover letter.";
            return;
        }
        AdvanceStep();
    }

    private void AdvanceStep()
    {
        if (currentStep > highestCompletedStep)
            highestCompletedStep = currentStep;
        currentStep++;
    }

    // Work entries
    private void AddWorkEntry() => workEntries.Add(new WorkEntryModel());
    private void RemoveWorkEntry(int index) => workEntries.RemoveAt(index);

    // References
    private void AddReference()
    {
        if (references.Count < 3) references.Add(new ReferenceModel());
    }
    private void RemoveReference(int index) => references.RemoveAt(index);

    // Submit
    private async Task SubmitApplication()
    {
        isProcessing = true;
        errorMessage = "";

        try
        {
            var personal = new PersonalInfo(fullName, email, phone, address);
            var work = new WorkHistory(workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description ?? "")
            ).ToList());
            var refs = references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, work, refs, coverLetter);

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isProcessing = false;
        }
    }

    // View models for mutable binding
    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 1.5rem 0;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #6c757d;
}

.step.active .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step.dimmed .step-circle {
    opacity: 0.5;
}

.step-label {
    margin-top: 0.4rem;
    font-size: 0.75rem;
    text-align: center;
    color: #6c757d;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step.dimmed .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    min-width: 20px;
    max-width: 60px;
    align-self: center;
    margin-bottom: 1.2rem;
}

.step-connector.completed {
    background: #198754;
}

.step-content {
    max-width: 720px;
    margin: 0 auto;
}

