@page "/apply"
@rendermode InteractiveServer
@using sv_2459d1cd92d4412e91c249149d3ab048.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@* Step Indicator Bar *@
<div class="step-indicator">
    @for (int i = 0; i < stepNames.Length; i++)
    {
        var stepIndex = i;
        var cssClass = GetStepClass(stepIndex);
        <div class="step @cssClass" @onclick="() => GoToStep(stepIndex)">
            <div class="step-circle">
                @if (stepIndex < currentStep)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@stepNames[stepIndex]</div>
        </div>
        @if (i < stepNames.Length - 1)
        {
            <div class="step-connector @(stepIndex < currentStep ? "completed" : "")"></div>
        }
    }
</div>

@if (!string.IsNullOrEmpty(errorMessage))
{
    <div class="alert alert-danger mt-3">@errorMessage</div>
}

@* Step Content *@
<div class="step-content mt-4">
    @switch (currentStep)
    {
        case 0:
            @* Personal Info *@
            <h3>Personal Information</h3>
            <div class="mb-3">
                <label class="form-label">Full Name *</label>
                <input type="text" class="form-control" @bind="fullName" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email *</label>
                <input type="email" class="form-control" @bind="email" />
            </div>
            <div class="mb-3">
                <label class="form-label">Phone *</label>
                <input type="tel" class="form-control" @bind="phone" />
            </div>
            <div class="mb-3">
                <label class="form-label">Address *</label>
                <input type="text" class="form-control" @bind="address" />
            </div>
            <div class="d-flex justify-content-end">
                <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@isProcessing">
                    @if (isProcessing) { <span>Validating...</span> } else { <span>Next</span> }
                </button>
            </div>
            break;

        case 1:
            @* Work History *@
            <h3>Work History</h3>
            @for (int i = 0; i < workEntries.Count; i++)
            {
                var idx = i;
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h5 class="card-title mb-0">Position @(idx + 1)</h5>
                            @if (workEntries.Count > 1)
                            {
                                <button class="btn btn-sm btn-outline-danger" @onclick="() => RemoveWorkEntry(idx)">Remove</button>
                            }
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Company Name *</label>
                            <input type="text" class="form-control" @bind="workEntries[idx].Company" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Job Title *</label>
                            <input type="text" class="form-control" @bind="workEntries[idx].Title" />
                        </div>
                        <div class="row mb-3">
                            <div class="col-md-6">
                                <label class="form-label">Start Date *</label>
                                <input type="date" class="form-control" @bind="workEntries[idx].StartDate" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">End Date</label>
                                <input type="date" class="form-control" @bind="workEntries[idx].EndDate" disabled="@workEntries[idx].IsCurrent" />
                                <div class="form-check mt-1">
                                    <input type="checkbox" class="form-check-input" id="current-@idx" @bind="workEntries[idx].IsCurrent" />
                                    <label class="form-check-label" for="current-@idx">Currently working here</label>
                                </div>
                            </div>
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Description</label>
                            <textarea class="form-control" rows="3" @bind="workEntries[idx].Description"></textarea>
                        </div>
                    </div>
                </div>
            }
            <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="Back">Back</button>
                <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
            </div>
            break;

        case 2:
            @* References *@
            <h3>References</h3>
            @for (int i = 0; i < references.Count; i++)
            {
                var idx = i;
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h5 class="card-title mb-0">Reference @(idx + 1)</h5>
                            @if (references.Count > 2)
                            {
                                <button class="btn btn-sm btn-outline-danger" @onclick="() => RemoveReference(idx)">Remove</button>
                            }
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Name *</label>
                            <input type="text" class="form-control" @bind="references[idx].Name" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Relationship *</label>
                            <input type="text" class="form-control" @bind="references[idx].Relationship" />
                        </div>
                        <div class="row mb-3">
                            <div class="col-md-6">
                                <label class="form-label">Email *</label>
                                <input type="email" class="form-control" @bind="references[idx].Email" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Phone *</label>
                                <input type="tel" class="form-control" @bind="references[idx].Phone" />
                            </div>
                        </div>
                    </div>
                </div>
            }
            @if (references.Count < 3)
            {
                <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
            }
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="Back">Back</button>
                <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
            </div>
            break;

        case 3:
            @* Cover Letter *@
            <h3>Cover Letter</h3>
            <div class="mb-3">
                <textarea class="form-control" rows="12" maxlength="2000" @bind="coverLetter" @bind:event="oninput"></textarea>
                <div class="form-text text-end">@coverLetter.Length / 2000 characters</div>
            </div>
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="Back">Back</button>
                <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
            </div>
            break;

        case 4:
            @* Review & Submit *@
            @if (isSubmitted)
            {
                <div class="alert alert-success">
                    <h4>Application Submitted Successfully!</h4>
                    <p>Your application ID is: <strong>@applicationId</strong></p>
                </div>
            }
            else
            {
                <h3>Review & Submit</h3>

                @* Personal Info Summary *@
                <div class="card mb-3">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>Personal Information</strong>
                        <a href="javascript:void(0)" @onclick='() => GoToStep(0)'>Edit</a>
                    </div>
                    <div class="card-body">
                        <p><strong>Name:</strong> @fullName</p>
                        <p><strong>Email:</strong> @email</p>
                        <p><strong>Phone:</strong> @phone</p>
                        <p><strong>Address:</strong> @address</p>
                    </div>
                </div>

                @* Work History Summary *@
                <div class="card mb-3">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>Work History</strong>
                        <a href="javascript:void(0)" @onclick='() => GoToStep(1)'>Edit</a>
                    </div>
                    <div class="card-body">
                        @foreach (var entry in workEntries)
                        {
                            <div class="mb-2">
                                <p class="mb-1"><strong>@entry.Title</strong> at @entry.Company</p>
                                <p class="mb-1 text-muted">
                                    @entry.StartDate.ToString("MMM yyyy") &ndash;
                                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                                </p>
                                @if (!string.IsNullOrWhiteSpace(entry.Description))
                                {
                                    <p class="mb-0">@entry.Description</p>
                                }
                            </div>
                            <hr />
                        }
                    </div>
                </div>

                @* References Summary *@
                <div class="card mb-3">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>References</strong>
                        <a href="javascript:void(0)" @onclick='() => GoToStep(2)'>Edit</a>
                    </div>
                    <div class="card-body">
                        @foreach (var r in references)
                        {
                            <p class="mb-1"><strong>@r.Name</strong> (@r.Relationship) &mdash; @r.Email, @r.Phone</p>
                        }
                    </div>
                </div>

                @* Cover Letter Summary *@
                <div class="card mb-3">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>Cover Letter</strong>
                        <a href="javascript:void(0)" @onclick='() => GoToStep(3)'>Edit</a>
                    </div>
                    <div class="card-body">
                        <p style="white-space: pre-wrap;">@coverLetter</p>
                    </div>
                </div>

                <div class="d-flex justify-content-between">
                    <button class="btn btn-secondary" @onclick="Back">Back</button>
                    <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@isProcessing">
                        @if (isProcessing) { <span>Submitting...</span> } else { <span>Submit Application</span> }
                    </button>
                </div>
            }
            break;
    }
</div>

